"""Public coverage and in-memory picture-null controls. Never opens the hidden split."""
from collections import Counter
from functools import lru_cache
import json
from pathlib import Path
import random
from unittest.mock import patch

from vs import corpus, dsl, generators, ivtff, registry

WORK = Path(__file__).resolve().parent
SEEDS = (31, 57, 83, 107, 139, 167, 199, 227)
MIN_OBJECTS = 20
PERMS = 399


def preflight():
    items = registry.read('picture')
    records = [i for i in items if i.get('verdict') == 'AGREED']
    gate = {'record_counts': dict(Counter(i['verdict'] for i in items)),
            'agreed_records': [i['id'] for i in records], 'main_checkout': 'e160993',
            'distinct_picture_folios': len({i['detail']['folio'] for i in items}),
            'runtime_selected': {}, 'all_agreed_record_counters': [], 'practice': {}}
    for folio, objects in dsl.pictures().items():
        gate['runtime_selected'][folio] = {'objects': len(objects),
            'direct_loci': sum(bool(o.get('label')) for o in objects),
            'joined_loci': len(dsl._joined_labels(folio, objects))}
    for item in records:
        folio = item['detail']['folio']
        objects = item['detail']['objects']
        labels = {o['label'] for o in objects if o.get('label')}
        row = {'id': item['id'], 'folio':folio, 'objects':len(objects),
               'explicit_loci':len(labels), 'agreement':item.get('agreement'), 'transliterations':{}}
        for transliteration in ('zl', 'it', 'rf'):
            p = next(page for page in corpus.pages(transliteration) if page.id == folio)
            native = {l.id for l in p.lines if l.unit == 'L' and l.words}
            with patch.object(dsl, 'PICTURES', {folio: objects}):
                usable = dsl._picture_objects(dsl.tokens([p], None))
            alike = sum(x[1] == y[1] and any(x[2].get(k) == v for k,v in y[2].items())
                       for idx,x in enumerate(usable) for y in usable[idx+1:])
            row['transliterations'][transliteration] = {'P_lines':sum(l.unit=='P' and bool(l.words) for l in p.lines),
                'L_lines':len(native),'valid_explicit_loci':len(labels&native), 'hypothetically_usable':len(usable),
                'alike_pairs':alike,'other_pairs':len(usable)*(len(usable)-1)//2-alike}
        gate['all_agreed_record_counters'].append(row)
    for transliteration in ('zl','it','rf'):
        _, practice = corpus.split_pages('practice', transliteration)
        tokens = dsl.tokens(practice, None)
        gate['practice'][transliteration] = {'joined':len(dsl._picture_objects(tokens)),
                                              'P_pages':len({t['folio'] for t in tokens if t['unit']=='P'})}
    return gate


def fixtures():
    pages = []
    primary, sham, balanced = {}, {}, {}
    for k in range(12):
        page_id = f'example{k+1:02d}'
        page = ivtff.Page(page_id, k, {'I':'H','L':'A','H':'1'})
        pages.append(page)
        primary[page_id], sham[page_id], balanced[page_id] = [], [], []

        def add(unit,n):
            j = len(page.lines) + 1
            lid = f'{page_id}.{j}'
            page.lines.append(ivtff.Line(lid,page_id,j,unit,'0',['o']*n,False,False))
            return lid

        for t in range(6):
            add('P',8)
            a, b = add('L',1), add('L',1)
            if (k+t) % 2:
                a,b = b,a
            obj = {'id': f'figure{t+1}', 'kind':'star', 'features': {'shade': f's{1+k}'}, 'label':a}
            primary[page_id].append(obj)
            sham[page_id].append({**obj,'label':b})
            balanced[page_id].append({**obj,'features':{'shade':f's{1+t%3}'}})
            add('P',8)
    return pages, (primary, sham, balanced)


def shape_preserving_shuffle(pages, seed):
    words = [word for p in pages for line in p.lines for word in line.words]
    random.Random(f'{seed}/global-slot-shuffle').shuffle(words)
    filler = iter(words)
    out = []
    for p in pages:
        q = ivtff.Page(p.id,p.order,dict(p.meta))
        out.append(q)
        for line in p.lines:
            q.lines.append(ivtff.Line(line.id,line.page,line.n,line.unit,line.subtype,
                                    [next(filler) for _ in line.words],line.para_start,line.para_end))
    return out


def spec(statistic):
    return {'statistic':{'picture_label':{'test':statistic,'min_objects':MIN_OBJECTS}},
            'compare':[{'op':'>','value':0},
                       {'null':'shuffle_picture_labels','direction':'greater','perms':PERMS,'p':.01}]}


def evaluate(pages, objects, statistic):
    with patch.object(dsl,'PICTURES',objects):
        try:
            r = dsl.evaluate(spec(statistic), pages)
            n = len(dsl._picture_objects(dsl.tokens(pages,None)))
            return {'value':r['value'],'pass':r['pass'],'p':r['detail']['shuffle_picture_labels']['p'], 'objects':n}
        except dsl.SpecError as e:
            return {'undefined':str(e)}


def main():
    public = preflight()
    (WORK/'public-gate.json').write_text(json.dumps(public,indent=2,ensure_ascii=False)+'\n')
    train, _ = corpus.split_pages('practice')
    shape, (primary, sham, balanced) = fixtures()
    results = {}
    # Cache equality-preserving computations on the tiny synthetic fixture. No evaluator is replaced.
    cached_pairs = lru_cache(maxsize=None)(dsl._glyph_pairs)
    with patch.object(dsl, '_glyph_pairs', cached_pairs):
        for seed in SEEDS:
            generated = generators.g_self_citation(train, shape, seed)
            mixed = shape_preserving_shuffle(generated, seed)
            results[seed] = {
                'page_reuse_label_recurrence': evaluate(generated, primary, 'label_in_page_text'),
                'page_reuse_sham_recurrence': evaluate(generated, sham, 'label_in_page_text'),
                'shuffled_slot_recurrence': evaluate(mixed, primary, 'label_in_page_text'),
                'page_clustered_feature_share': evaluate(generated, primary, 'feature_label_share'),
                'balanced_feature_share': evaluate(generated, balanced, 'feature_label_share'),
                'shuffled_slot_feature_share': evaluate(mixed, primary, 'feature_label_share'),
            }
            (WORK/'synthetic-result.json').write_text(json.dumps(results,indent=2)+'\n')
            print(seed, {k:(v.get('value'),v.get('p'),v.get('pass')) for k,v in results[seed].items()}, flush=True)


if __name__ == '__main__':
    main()

