from collections import defaultdict
import json
from pathlib import Path
from random import Random
from unittest.mock import patch

from audit_picture_gate import fixtures, WORK
from vs import corpus, dsl, generators


def within_page(tokens, rng):
    groups = defaultdict(dict)
    for tok in tokens:
        if tok['unit'] == 'L':
            groups[tok['folio']].setdefault(tok['lid'], []).append(tok['w'])
    assignment = {}
    for group in groups.values():
        old = list(group.values())
        rng.shuffle(old)
        assignment.update(zip(group, old))
    done = set()
    out = []
    for tok in tokens:
        lid = tok.get('lid')
        if lid not in assignment:
            out.append(tok)
        elif lid not in done:
            done.add(lid)
            ws = assignment[lid]
            out.extend(dict(tok,w=w,k=i,n=len(ws)) for i,w in enumerate(ws))
    return out


def main():
    train, _ = corpus.split_pages('practice')
    shape, (primary, _, _) = fixtures()
    out = {}
    # Use the primary labels only; preserve which lines are linked when permuting.
    rng = Random(37571)
    for seed in (31, 227):
        pages = generators.g_self_citation(train, shape, seed)
        tokens = dsl.tokens(pages,None)
        selected = {o['label'] for objs in primary.values() for o in objs}
        selected_lines = [tok for tok in tokens if tok['unit']=='L' and tok['lid'] in selected]
        p_text = [tok for tok in tokens if tok['unit']!='L']
        with patch.object(dsl,'PICTURES',primary):
            metrics = ('label_in_page_text','feature_label_share')
            values = {name:dsl._picture_label(name,p_text+selected_lines,20) for name in metrics}
            moves = {name:[] for name in metrics}
            for i in range(25):
                s = within_page(p_text+selected_lines,rng)
                for name in metrics:
                    moves[name].append(abs(dsl._picture_label(name,s,20)-values[name]))
        out[seed] = {name:{'observed':values[name], 'draws':25, 'largest_absolute_change':max(moves[name])} for name in metrics}
        assert all(row['largest_absolute_change'] < 1e-12 for row in out[seed].values())
    (WORK/'within-page-result.json').write_text(json.dumps(out,indent=2)+'\n')
    print(json.dumps(out,indent=2))


if __name__=='__main__':
    main()

programs.paired_control.py:
"""Same-folio same-length selected/sham control for synthetic fixture labels."""
from collections import defaultdict
import json
from random import Random
from statistics import mean

from audit_picture_gate import fixtures, SEEDS, PERMS, WORK
from vs import corpus, dsl, generators


def paired_hits(pages, primary, sham):
    tok = dsl.tokens(pages, None)
    ptext = defaultdict(set)
    labels = {}
    for t in tok:
        if t['unit'] == 'P':
            ptext[t['folio']].add(t['w'])
        elif t['unit'] == 'L':
            assert t['lid'] not in labels
            labels[t['lid']] = t['w']

    def rate(word, fid):
        return int(word in ptext[fid]) - mean(word in words for f,words in ptext.items() if f!=fid)

    pairs = []
    for fid in primary:
        by_size = [defaultdict(list), defaultdict(list)]
        for index, items in enumerate((primary[fid],sham[fid])):
            for obj in items:
                word = labels[obj['label']]
                size = len(dsl.SEG(word))
                if size >= 3:
                    by_size[index][size].append(word)
        for size in sorted(by_size[0].keys() & by_size[1].keys()):
            pairs.extend(rate(a,fid)-rate(b,fid) for a,b in zip(by_size[0][size],by_size[1][size]))
    return pairs


def main():
    train, _ = corpus.split_pages('practice')
    shape, (primary, sham, _) = fixtures()
    result = {}
    for seed in SEEDS:
        pages = generators.g_self_citation(train, shape, seed)
        values = paired_hits(pages, primary, sham)
        actual = mean(values) if values else None
        rng = Random(f'{seed}/paired-label-control')
        moved = sum(mean(val*rng.choice((-1,1)) for val in values) >= actual-1e-12 for _ in range(PERMS)) if values else None
        p = (moved + 1)/(PERMS + 1) if moved is not None else None
        result[seed] = {'matched_pairs':len(values), 'mean_primary_minus_sham':round(actual,6) if actual is not None else None,
                        'perm_p':p,'passes':len(values)>=20 and actual>0 and p<=.01}
    (WORK/'paired-result.json').write_text(json.dumps(result,indent=2)+'\n')
    print(json.dumps(result,indent=2))


if __name__=='__main__':
    main()
